import {SKILLS,DAY,dateKey,fresh,skillState,status,progress,problem,record,finishRecall,pickSkill} from './engine.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');const KEY='nerdy-pip-v1';let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!state||state.version!==1)state=fresh();}catch{state=fresh()}
let page='adventure',lesson=null,world=0,storeWarning=false;const worldNames=['Little Meadow','Canopy Grove','Wonder Lagoon','Starlight Summit'];
const icons={adventure:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z"/><path d="M9 3v15m6-12v15"/>',skills:'<path d="m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5"/>',collection:'<rect x="4" y="7" width="16" height="14" rx="3"/><path d="M2 7h20M12 7v14M12 7C5 7 5 1 8 2c3 0 4 5 4 5s1-5 4-5c3-1 3 5-4 5"/>',parent:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5zM15 8c3 2 3 6 0 8m3-11c5 4 5 10 0 14"/>',gear:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[k]||icons.adventure}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{if(!storeWarning){storeWarning=true;toast('This browser cannot save progress. Keep this tab open.')}}}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function todayCount(){return state.attempts.filter(a=>dateKey(a.at)===dateKey()&&a.ok&&!a.hint).length}
function nav(next){page=next;render();window.scrollTo(0,0)}
function render(){app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">n</span><span class="word">nerdy</span><small>PLAY TO GROW</small></div><nav class="nav" aria-label="Main navigation">${[['adventure','My adventure'],['skills','Math powers'],['collection','My treasures'],['parent','For grown-ups']].map(([id,name])=>`<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}<span class="nav-label">${name}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="friend-note"><span class="leaf">🌱</span>Little steps.<br><strong>Wonderful possibilities.</strong></div><button class="parent-nav" data-action="settings">${icon('gear')} Settings</button></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">nerdy <span class="crumb-path"> / </span><b>${{adventure:'My adventure',skills:'Math powers',collection:'My treasures',parent:'For grown-ups'}[page]}</b></div><div class="topstats"><div class="stat" title="Days explored — breaks never erase progress"><span>☀️</span>${state.days.length}<span class="small muted">days</span></div><div class="stat" title="Seeds earned through learning"><span>✦</span>${state.seeds}</div><button class="profile" data-action="settings" aria-label="Explorer settings">${state.avatar}</button></div></header>${page==='adventure'?home():page==='skills'?skillsPage():page==='collection'?collectionPage():parentPage()}<p class="footer-note">Made for curious minds. A little progress is a lovely thing.</p></main></div>`;bind();}
function home(){const id=pickSkill(state),skill=SKILLS.find(s=>s.id===id);return `<section class="greeting"><div><h1>Your next little adventure <span aria-hidden="true">☀️</span></h1><p>Hey ${esc(state.name)}, a world of wonder is waiting.</p></div><div class="day-pill">🌿 No rush. Just a little discovery.</div></section><div class="dashboard"><div><section class="world-card" aria-label="${worldNames[world]} adventure map"><img class="world-art" src="world.png" alt="Pip, a little leaf-eared explorer, on a floating green island with a pond and an observatory"><div class="world-label"><div class="eyebrow">YOUR WORLD · ${String(world+1).padStart(2,'0')}</div><h2>${worldNames[world]}</h2><p>${['Big discoveries start small.','Good things grow together.','A sea of possibilities.','Reach for a new possibility.'][world]}</p></div><button class="world-switch" data-action="world" aria-label="Explore next world">${icon('arrow')}</button><button class="island-marker past" data-start="${['count','place','fraction','decimal'][world]}" aria-label="Explore ${['counting','place value','fractions','decimals'][world]}">✦</button><button class="island-marker current" data-start="${id}" aria-label="Start your next adventure">▶</button><div class="marker-label">Let’s explore!</div><button class="island-marker next" data-start="${['geometry','multiply','measure','divide'][world]}" aria-label="Explore another math power">${['△','×','↔','÷'][world]}</button><div class="world-bottom"><span>🌱 ${state.sessions.length} adventures together</span><div class="dots" aria-hidden="true">${worldNames.map((_,i)=>`<i style="${i===world?'background:white;width:20px':'background:#ffffff80;width:6px'}"></i>`).join('')}</div></div></section><section class="journey-card"><div class="quest-icon">🧭</div><div class="journey-copy"><div class="eyebrow">${skillState(state,id).due<=Date.now()&&skillState(state,id).due?'A LITTLE REVISIT':'YOUR NEXT ADVENTURE'}</div><h3>${skill.name} with Pip</h3><p>6 little challenges · About 3 minutes · + seeds</p></div><button class="primary" data-start="${id}">Let’s play ${icon('arrow')}</button></section></div><aside class="rail"><section class="panel"><div class="panel-head"><h3>A little, often</h3><span class="tag">${state.days.length} days explored</span></div><p class="small muted">Room to grow, every day.</p>${week()}<p class="habit-note">Miss a day? Pip will still be here. ♡</p></section><section class="panel"><div class="panel-head"><h3>Today’s tiny quest</h3><span aria-hidden="true">✧</span></div><div class="daily"><span class="daily-emoji">🌧️</span><div><strong>Make a little rain</strong><p>Help 6 ideas bloom.</p></div></div><div class="bar"><span style="width:${Math.min(100,todayCount()/6*100)}%"></span></div><div class="bar-label"><span>${Math.min(6,todayCount())} / 6 discoveries</span><span>🌱 + growth</span></div></section><section class="panel companion"><div class="eyebrow">YOUR ADVENTURE BUDDY</div><h3>Pip’s glad you’re here.</h3><p>“I wonder what we’ll figure out together?”</p><span class="pip-mini" aria-hidden="true">🌱</span><button class="text-button" data-nav="collection" style="margin-top:17px">Visit our treasures →</button></section></aside></div><div class="section-title"><h2>Growing your math powers</h2><button class="text-button" data-nav="skills">See all powers →</button></div><div class="skill-grid">${SKILLS.filter(s=>s.min<=state.grade).slice(0,3).map(skillCard).join('')}</div>`}
function week(){const now=new Date(),monday=new Date(now);monday.setDate(now.getDate()-((now.getDay()+6)%7));return `<div class="week">${['M','T','W','T','F','S','S'].map((day,i)=>{const d=new Date(monday);d.setDate(monday.getDate()+i);const key=dateKey(d.getTime()),done=state.days.includes(key);return `<div class="week-day ${key===dateKey()?'today':''} ${done?'done':''}">${day}<b aria-label="${key}${done?', explored':''}">${done?'✓':key===dateKey()?'☀':'·'}</b></div>`}).join('')}</div>`}
function skillCard(s){const st=skillState(state,s.id);return `<button class="skill-card" data-start="${s.id}"><div class="skill-top"><span class="skill-symbol">${s.symbol}</span><span class="tag">${status(st)}</span></div><h3>${s.name}</h3><p>${s.desc}</p><div class="bar" aria-label="${progress(st)} percent of evidence milestones"><span style="width:${progress(st)}%"></span></div></button>`}
function skillsPage(){return `<section class="greeting"><div><h1>Small discoveries. Real powers.</h1><p>Pick a starting point. We’ll find your rhythm together.</p></div></section><div class="wide-panel"><h3>Where shall we begin?</h3><p class="small muted">A starting level, never a label. You can explore every power.</p><div class="grade-row" role="group" aria-label="Starting grade">${[0,1,2,3,4,5].map(g=>`<button class="grade-btn ${g===state.grade?'selected':''}" data-grade="${g}" aria-pressed="${g===state.grade}">${g===0?'K':g}</button>`).join('')}</div><p class="small muted">Your recommended powers for ${state.grade?'grade '+state.grade:'kindergarten'} are shown first.</p></div><div class="section-title"><h2>Explore the whole world</h2><span class="small muted">10 math powers</span></div><div class="skill-grid all-skills">${[...SKILLS].sort((a,b)=>(a.min>state.grade)-(b.min>state.grade)).map(skillCard).join('')}</div><div class="info">🌱 Practice helps a power grow. Remembering it on different days makes it last. The green bars show collected learning evidence, not curriculum completion.</div>`}
const treasures=[{icon:'🌱',name:'Little sprout',at:0,desc:'Every explorer starts somewhere.'},{icon:'🦊',name:'Meadow fox',at:1,desc:'Finish your first adventure.'},{icon:'🐸',name:'Pond pal',at:3,desc:'Explore on 3 adventures.'},{icon:'🦉',name:'Moon watcher',at:6,desc:'Discover through 6 adventures.'},{icon:'🦋',name:'Sky wanderer',at:10,desc:'Spread your wings in 10 adventures.'},{icon:'🐉',name:'Wonder dragon',at:20,desc:'Grow through 20 adventures.'}];
function collectionPage(){return `<section class="greeting"><div><h1>A pocketful of possibilities</h1><p>Friends earned by learning. Yours to keep, always.</p></div><div class="day-pill">✦ ${state.seeds} seeds collected</div></section><div class="collection-grid">${treasures.map(t=>{const unlocked=state.sessions.length>=t.at;return `<div class="collectible ${unlocked?'':'locked'}"><div class="collect-icon" aria-hidden="true">${t.icon}</div><h3>${t.name}</h3><p>${t.desc}</p><button class="secondary" data-equip="${t.icon}" ${unlocked?'':'disabled'}>${unlocked?state.avatar===t.icon?'Your explorer ✓':'Choose companion':`${state.sessions.length} / ${t.at} adventures`}</button></div>`}).join('')}</div><div class="info">Your seeds celebrate real discoveries. There’s nothing to buy, no rewards to lose, and no timer to beat. Each adventure earns seeds for independent answers; revisiting a power earns extra.</div>`}
function parentPage(){const attempts=state.attempts,independent=attempts.filter(a=>!a.hint),accuracy=independent.length?Math.round(independent.filter(a=>a.ok).length/independent.length*100)+'%':'—',remembered=Object.values(state.skills).filter(s=>s.checks>=3).length;return `<section class="greeting"><div><h1>See the learning behind the play.</h1><p>${esc(state.name)}’s learning journal · Saved on this device</p></div><button class="secondary" data-action="settings">Settings</button></section><div class="metric-row"><div class="metric"><div class="number">${state.sessions.length}</div><p>Adventures explored</p></div><div class="metric"><div class="number">${accuracy}</div><p>Unassisted accuracy</p></div><div class="metric"><div class="number">${remembered}</div><p>Powers remembered</p></div><div class="metric"><div class="number">${attempts.length}</div><p>First attempts observed</p></div></div><div class="wide-panel"><h2>Evidence, one power at a time</h2><p class="small muted" style="margin-top:7px">Only first attempts count. Using a hint stays visible in the evidence.</p><div class="table-scroll"><table class="evidence"><thead><tr><th>Math power</th><th>Independent accuracy</th><th>Recall checks</th><th>Learning stage</th><th>Next revisit</th></tr></thead><tbody>${SKILLS.map(s=>{const st=skillState(state,s.id),a=st.history.filter(a=>!a.hint);return `<tr><td><strong>${s.name}</strong></td><td>${a.length?Math.round(a.filter(a=>a.ok).length/a.length*100)+'% · '+a.length+' attempts':'Not enough evidence'}</td><td>${st.checks} / 3</td><td>${status(st)}</td><td>${st.due?st.due<=Date.now()?'Ready today':new Date(st.due).toLocaleDateString(undefined,{month:'short',day:'numeric'}):'After fluent practice'}</td></tr>`}).join('')}</tbody></table></div></div><div class="info"><strong>What “remembered” means here</strong><br>At least 7 of the latest 8 answers correct without help, with 6 comfortable responses (45 seconds in K–1; 30 seconds later), then three successful recall checks across separate days. No countdown is shown. Comfortable pace mode removes the time criterion. Recall returns after spaced intervals, including after a power is remembered.<br><br><strong>Honest evidence:</strong> this is a working learning prototype, not a validated curriculum or proof of learning gains. The journal records accuracy, difficulty, response time, hints, and delayed recall. A controlled learning study and broader curriculum assessment are needed to establish effectiveness.</div><div class="wide-panel"><h2>Recent adventures</h2>${state.sessions.length?state.sessions.slice(-5).reverse().map(s=>`<div class="panel-head" style="margin:17px 0 0"><div><strong>${SKILLS.find(x=>x.id===s.id)?.name||'Math'} with Pip</strong><p class="small muted">${new Date(s.at).toLocaleDateString()} · ${s.correct} / ${s.total} independent answers</p></div><span class="tag">+${s.seeds} seeds</span></div>`).join(''):'<p class="empty">Your first adventure will plant the first piece of evidence.</p>'}<div class="parent-actions"><button class="secondary" data-action="export">Download learning journal</button><button class="text-button" data-action="reset">Clear this device’s progress</button></div></div>`}
function bind(){app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));app.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));app.querySelectorAll('[data-grade]').forEach(b=>b.onclick=()=>{state.grade=Number(b.dataset.grade);save();render()});app.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{const t=treasures.find(t=>t.icon===b.dataset.equip);if(state.sessions.length<t.at)return;state.avatar=t.icon;save();render();toast('A new friend for your next adventure!')});app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));}
function action(a){if(a==='world'){world=(world+1)%4;render()}if(a==='settings')settings();if(a==='export'){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='nerdy-learning-journal.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your learning journal has been downloaded.')}if(a==='reset'){modal.innerHTML='<h2>A fresh beginning?</h2><p>This removes all learning evidence and treasures saved in this browser. Download the journal first if you want to keep it.</p><div class="dialog-actions"><button class="secondary" id="cancel">Keep progress</button><button class="primary" id="confirm">Clear progress</button></div>';modal.showModal();$('#cancel').onclick=()=>modal.close();$('#confirm').onclick=()=>{state=fresh();save();modal.close();render()}}}
function settings(){modal.innerHTML=`<h2>Your explorer</h2><p>Make a little room for your own way to learn.</p><label for="name">Explorer name</label><input id="name" maxlength="24" value="${esc(state.name)}" autocomplete="off"><label for="grade">Starting grade</label><select id="grade">${[0,1,2,3,4,5].map(g=>`<option value="${g}" ${g===state.grade?'selected':''}>${g?'Grade '+g:'Kindergarten'}</option>`).join('')}</select><label for="pace">Learning pace</label><select id="pace"><option value="normal" ${!state.untimed?'selected':''}>Gentle fluency · no visible timer</option><option value="untimed" ${state.untimed?'selected':''}>Comfortable pace · accuracy only</option></select><label for="sound">Celebration sounds</label><select id="sound"><option value="off" ${!state.sound?'selected':''}>Off</option><option value="on" ${state.sound?'selected':''}>On</option></select><p class="small" style="margin-top:17px">Progress stays in this browser. No child account or personal details are needed.</p><div class="dialog-actions"><button class="secondary" id="cancel">Cancel</button><button class="primary" id="save-settings">Save</button></div>`;modal.showModal();$('#cancel').onclick=()=>modal.close();$('#save-settings').onclick=()=>{state.name=$('#name').value.trim()||'Explorer';state.grade=Number($('#grade').value);state.untimed=$('#pace').value==='untimed';state.sound=$('#sound').value==='on';save();modal.close();render()}}
function start(id){if(!SKILLS.some(s=>s.id===id))throw Error('Unknown math power');const s=skillState(state,id);lesson={id,index:0,total:6,correct:0,seeds:0,results:[],recall:!!s.due&&s.due<=Date.now(),done:false};nextProblem();window.scrollTo(0,0)}
function nextProblem(){const s=skillState(state,lesson.id);lesson.q=problem(lesson.id,s.level,state.grade);lesson.started=performance.now();lesson.hinted=false;lesson.answered=false;lesson.retries=0;renderLesson()}
function dots(n,gold=false){return `<div class="counters">${Array.from({length:Math.ceil(n/5)*5},(_,i)=>`<span class="counter ${i>=n?'empty':gold?'gold':''}"></span>`).join('')}</div>`}
function visual(v){if(!v)return '';if(v.type==='count')return dots(v.a);if(v.type==='add')return dots(v.a)+`<span class="visual-sign">+</span>`+dots(v.b,true);if(v.type==='subtract')return dots(v.a)+`<span class="visual-sign">− ${v.b}</span>`;if(v.type==='groups')return Array.from({length:v.a},()=>dots(v.b)).join('');if(v.type==='fraction')return `<div class="fraction-strip">${Array.from({length:v.b},(_,i)=>`<span class="${i<v.a?'fill':''}"></span>`).join('')}</div>`;if(v.type==='shape')return `<div class="shape ${v.shape}" role="img" aria-label="${v.shape}"></div>`;return ''}
function renderLesson(){const q=lesson.q,skill=SKILLS.find(s=>s.id===lesson.id);app.innerHTML=`<main class="session"><div class="session-top"><button class="close" id="exit-lesson" aria-label="Leave adventure">×</button><div class="bar" role="progressbar" aria-valuemin="0" aria-valuemax="6" aria-valuenow="${lesson.index}" aria-label="Adventure progress"><span style="width:${lesson.index/lesson.total*100}%"></span></div><span class="stat">✦ ${lesson.seeds}</span></div><div class="lesson-meta"><span>${skill.name} · ${lesson.recall?'A little revisit':'Growing together'}</span><span>${lesson.index+1} of ${lesson.total}</span></div><section class="problem"><h1>${q.prompt}</h1><p>Pip’s here. Take your time.</p>${q.display?`<div class="math-display">${q.display}</div>`:''}<div class="visual" ${q.visual&&q.visual.type!=='shape'?'aria-label="Visual math model"':''}>${visual(q.visual)}</div><button class="text-button" id="read-question">${icon('sound')} <span>Listen</span></button></section><div class="answers" role="group" aria-label="Choose your answer">${q.choices.map((c,i)=>`<button class="answer" data-answer="${i}"><span class="key">${i+1}</span>${c}</button>`).join('')}</div><div id="hint-area"></div><div class="lesson-bottom"><div class="feedback" id="feedback" aria-live="polite"><button class="secondary" id="hint-button">☼ A little help</button></div><button class="primary" id="next-question" hidden>Keep exploring ${icon('arrow')}</button></div><p class="footer-note">Every try helps us find the next right step. ♡</p></main>`;$('#next-question').style.display='none';$('#exit-lesson').onclick=exitLesson;$('#hint-button').onclick=showHint;$('#read-question').onclick=()=>{if(!('speechSynthesis'in window)){toast('Read-aloud is not available in this browser.');return;}speechSynthesis.cancel();const text=`${q.prompt} ${q.display.replaceAll('×',' times ').replaceAll('÷',' divided by ').replaceAll('−',' minus ').replaceAll('= ?',' equals what?')}`;const u=new SpeechSynthesisUtterance(text);u.lang='en';u.rate=.8;speechSynthesis.speak(u)};app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer)));$('#next-question').onclick=advance;}
function showHint(){if(!lesson||lesson.answered)return;lesson.hinted=true;$('#hint-area').innerHTML=`<div class="hint">🌱 ${lesson.q.hint}</div>`;$('#hint-button').disabled=true;}
function answer(i){if(!lesson||lesson.done||lesson.answered)return;const q=lesson.q;if(!Number.isInteger(i)||i<0||i>=q.choices.length)return;const ok=q.choices[i]===q.answer;const b=app.querySelector(`[data-answer="${i}"]`);if(b.disabled)return;b.classList.add(ok?'correct':'wrong');b.disabled=true;
 if(!lesson.retries){const a=record(state,{id:lesson.id,ok,hint:lesson.hinted,ms:performance.now()-lesson.started,recall:lesson.recall&&lesson.index<3});lesson.results.push(a);if(ok&&!lesson.hinted){lesson.correct++;lesson.seeds+=lesson.recall?4:3;}save();}
 if(!ok){lesson.retries++;lesson.hinted=true;$('#feedback').innerHTML='<strong>Let’s look together.</strong>Try another answer. Your learning is safe.';$('#hint-area').innerHTML=`<div class="hint">🌱 ${q.hint}</div>`;return;}
 lesson.answered=true;app.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);$('#feedback').innerHTML=`<strong>${lesson.retries?'You figured it out!':lesson.hinted?'Good thinking together!':['A little discovery!','You’ve got it!','Beautiful thinking!'][lesson.index%3]}</strong>${lesson.retries||lesson.hinted?'A little help is part of learning.':`+${lesson.recall?4:3} seeds for independent thinking.`}`;$('#next-question').hidden=false;$('#next-question').style.display='inline-flex';$('#next-question').textContent=lesson.index===5?'See what grew →':'Keep exploring →';$('#next-question').focus();if(state.sound)chime();}
function advance(){if(!lesson?.answered)return;lesson.index++;if(lesson.index>=lesson.total)finish();else nextProblem()}
function finish(){if(lesson.done)return;lesson.done=true;if(lesson.recall)finishRecall(state,lesson.id,lesson.results.slice(0,3));const before=state.sessions.length;state.seeds+=lesson.seeds;if(!state.days.includes(dateKey()))state.days.push(dateKey());state.sessions.push({id:lesson.id,at:Date.now(),correct:lesson.correct,total:lesson.total,seeds:lesson.seeds,recall:lesson.recall});save();const newFriend=treasures.find(t=>t.at>before&&t.at<=state.sessions.length);app.innerHTML=`<main class="session finish"><div class="celebrate">${newFriend?newFriend.icon:'🌿'}</div><div class="eyebrow" style="color:#7e9e7f;margin-bottom:12px">A LITTLE MORE WONDER</div><h1>Look what grew today.</h1><p>${newFriend?`You met ${newFriend.name.toLowerCase()}! A new friend for your adventures.`:'Your ideas are taking root. Pip can’t wait to explore with you again.'}</p><div class="finish-stats"><div><strong>+${lesson.seeds}</strong><small>Seeds earned</small></div><div><strong>${lesson.correct} / 6</strong><small>On your own</small></div><div><strong>${state.days.length}</strong><small>Days explored</small></div></div><div class="info">${skillState(state,lesson.id).due?'We’ll revisit this power another day to help it stay with you.':'Every try helps us choose the next challenge that fits you.'}<br>That’s enough for today, if you like. Your world will be here.</div><button class="primary" id="back-home">Back to my world ${icon('arrow')}</button><div style="margin-top:22px"><button class="text-button" id="play-again">I’d like another little adventure</button></div></main>`;$('#back-home').onclick=()=>{lesson=null;nav('adventure')};$('#play-again').onclick=()=>start(pickSkill(state));}
function exitLesson(){modal.innerHTML='<h2>Take a little break?</h2><p>Your learning evidence is saved. Finish this adventure to collect its seeds and meet new friends.</p><div class="dialog-actions"><button class="secondary" id="leave">Back to my world</button><button class="primary" id="stay">Keep exploring</button></div>';modal.showModal();$('#stay').onclick=()=>modal.close();$('#leave').onclick=()=>{modal.close();lesson=null;nav('adventure')}}
function chime(){try{const C=window.AudioContext||window.webkitAudioContext,c=new C();[523,659,784].forEach((f,i)=>{const o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.value=f;g.gain.setValueAtTime(.035,c.currentTime+i*.09);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+i*.09+.23);o.start(c.currentTime+i*.09);o.stop(c.currentTime+i*.09+.24)});setTimeout(()=>c.close(),800)}catch{}}
document.addEventListener('keydown',e=>{if(modal.open||!lesson||lesson.done)return;if(['1','2','3','4'].includes(e.key)){e.preventDefault();answer(Number(e.key)-1)}});
render();
if(document.modelContext?.registerTool){try{void Promise.resolve(document.modelContext.registerTool({name:'read_learning_summary',description:'Read device-local learning evidence without modifying progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('This read-only tool takes an empty object.');return {sessions:state.sessions.length,skills:SKILLS.map(s=>({id:s.id,status:status(skillState(state,s.id)),recallChecks:skillState(state,s.id).checks}))}}})).catch(()=>{});}catch{}}

